import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第三十章 如何做到真正的不害？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/30第三十章 如何做到真正的不害.md","filePath":"meditation/巴利文大藏经/30第三十章 如何做到真正的不害.md"}'),r={name:"meditation/巴利文大藏经/30第三十章 如何做到真正的不害.md"};function _(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第三十章-如何做到真正的不害" tabindex="-1">第三十章 如何做到真正的不害？ <a class="header-anchor" href="#第三十章-如何做到真正的不害" aria-label="Permalink to &quot;第三十章 如何做到真正的不害？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部7相应5经/无害经(婆罗门相应/有偈篇/祇夜)</p><p>有个时候，不害婆罗门来到佛陀的住所，顶礼佛陀后，他在一旁坐下，不害婆罗门对佛陀说：“世尊，我的名字叫做不害，请您为我说法。”</p><p>佛陀说：“婆罗门，你的名字叫不害，什么才是名副其实的不害呢？也就是身体行为做善事，口说善言，内心生起善念，不伤害别人这才是真正的不害，你如果能够真正做到身体行为，口说言语，内心生起的念想不伤害别人，那么你就名如其人，你就是名副其实的不害。”</p><p>这时，佛陀说偈言：</p><p>「若如其名者，汝实为不害。</p><p>然而不害于，身口以及心。</p><p>以不害他者，始名实不害。」</p><p>佛陀说法后，不害婆罗门欢喜的对佛陀说：“世尊，您说的太好了，我会努力去做名副其实的不害婆罗门的，感谢世尊您为我说法，请让我皈依您，做您的在家修行弟子吧，我愿意按您的正法去修行，我愿意受持您制定的戒律。”</p><p>佛陀接受了不害婆罗门的皈依。</p>',11)]))}const f=e(r,[["render",_]]);export{m as __pageData,f as default};
